package org.apache.commons.math.optimization.linear;

import org.apache.commons.math.optimization.GoalType;
import org.apache.commons.math.optimization.RealPointValuePair;
import org.junit.Assert;
import org.junit.Test;

import java.util.ArrayList;
import java.util.Collection;

public class AgentBRT_Math_42_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        // Define the linear objective function
        LinearObjectiveFunction objectiveFunction = new LinearObjectiveFunction(new double[]{1, 1}, 0);

        // Define the constraints
        Collection<LinearConstraint> constraints = new ArrayList<>();
        constraints.add(new LinearConstraint(new double[]{1, -1}, Relationship.LEQ, 10));
        constraints.add(new LinearConstraint(new double[]{0, 1}, Relationship.LEQ, 20));
        constraints.add(new LinearConstraint(new double[]{0, 0}, Relationship.LEQ, 30));

        // Create the SimplexTableau
        SimplexTableau tableau = new SimplexTableau(
            objectiveFunction,
            constraints,
            GoalType.MAXIMIZE,
            true,
            1e-6
        );

        // Call getSolution and check the result
        RealPointValuePair solution = tableau.getSolution();
        double[] expectedCoefficients = {10, 20}; // Expected solution coefficients
        Assert.assertArrayEquals("The solution coefficients are incorrect due to the bug.",
                                 expectedCoefficients, solution.getPoint(), 1e-6);
    }
}

